// A package's explicit `tag-template` that equals another package's default tags is E101.
#[test]
fn an_explicit_tag_template_equal_to_another_packages_default_fails_with_e101() {
    let dir = repo();
    let root = dir.path();
    write(
        root,
        "Cargo.toml",
        "[workspace]\nmembers = [\"crates/*\"]\nresolver = \"2\"\n",
    );
    for name in ["a", "b"] {
        write(
            root,
            &format!("crates/{name}/Cargo.toml"),
            &format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n"),
        );
        write(root, &format!("crates/{name}/src/lib.rs"), "");
    }
    write(
        root,
        "callisto.toml",
        "[[package]]\nmatch = \"cargo/a\"\ntag-template = \"b@{version}\"\n",
    );
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "workspace"]);

    let out = callisto(root, &["status"]);
    assert_eq!(out.status.code(), Some(1), "stderr: {}", stderr_of(&out));
    assert!(stderr_of(&out).contains("E101"), "stderr: {}", stderr_of(&out));
    assert!(stderr_of(&out).contains("b@{version}"), "stderr: {}", stderr_of(&out));
}

